    .{ .cause = error.InvalidFlightIpc, .code = "flight.invalid_result_encoding", .category = .integrity, .stage = .output, .status = 15, .message = "The result does not match the verified Arrow schema or Flight IPC framing. No complete Flight result can be returned. Preserve the original query and result evidence; do not silently coerce cells or rerun SQL." },
    .{ .cause = error.InvalidArrowResult, .code = "flight.invalid_result_encoding", .category = .integrity, .stage = .output, .status = 15, .message = "The result does not match the verified Arrow schema or Flight IPC framing. No complete Flight result can be returned. Preserve the original query and result evidence; do not silently coerce cells or rerun SQL." },
